import{_ as a,o as s,c as n,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"远程 spawn","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/remote-spawn.md","filePath":"projects/lotus-plugin/docs/remote-spawn.md"}'),t={name:"projects/lotus-plugin/docs/remote-spawn.md"};function o(p,e,c,i,d,r){return s(),n("div",null,[...e[0]||(e[0]=[l(`<h1 id="远程-spawn" tabindex="-1">远程 spawn <a class="header-anchor" href="#远程-spawn" aria-label="Permalink to &quot;远程 spawn&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><p>远程命令、上传、下载都必须满足：</p><ul><li>bot master</li><li>2FA 一次性验证码</li><li>审计日志</li><li>输出脱敏</li><li>超时限制</li><li>输出长度限制</li></ul><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#远程2FA初始化</span></span>
<span class="line"><span>#远程2FA状态</span></span>
<span class="line"><span>#远程spawn &lt;otp&gt; &lt;shell&gt; &lt;command&gt;</span></span>
<span class="line"><span>#远程管理员spawn &lt;otp&gt; &lt;shell&gt; &lt;command&gt;</span></span>
<span class="line"><span>#远程下载 &lt;otp&gt; &lt;path&gt;</span></span>
<span class="line"><span>#远程上传 &lt;otp&gt; &lt;path&gt;</span></span>
<span class="line"><span>#远程上传覆盖 &lt;otp&gt; &lt;path&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><ul><li><code>otp</code>：必填，TOTP 应用显示的 6 位一次性验证码。</li><li><code>shell</code>：必填，支持 <code>pwsh</code>、<code>powershell</code>、<code>cmd</code>、<code>bash</code>、<code>sh</code>、<code>zsh</code>，主机必须已安装对应 Shell，且 <code>remote.shells</code> 白名单允许使用。</li><li><code>command</code>：必填，要执行的命令文本。</li><li><code>path</code>：必填，上传或下载的目标路径。</li></ul><p>首次使用先由 bot 主人执行 <code>#远程2FA初始化</code>。荷花插件会生成一张二维码，使用 Microsoft Authenticator 或其他 TOTP 应用扫码添加。之后远程命令、管理员 spawn、上传、下载都需要把应用里显示的 6 位一次性验证码写在指令里。</p><p>默认 secret 保存到 <code>data/remote/otp.yaml</code>。如果配置了环境变量 <code>LOTUS_REMOTE_OTP_SECRET</code>，会优先使用环境变量，适合容器或受控部署。</p><h2 id="linux-shell" tabindex="-1">Linux Shell <a class="header-anchor" href="#linux-shell" aria-label="Permalink to &quot;Linux Shell&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#远程spawn 123456 bash uname -a</span></span>
<span class="line"><span>#远程spawn 123456 sh df -h</span></span>
<span class="line"><span>#远程spawn 123456 zsh pwd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Linux Shell 使用 <code>-c</code> 执行完整命令文本，支持管道、重定向和多行命令。运行目录为 bot 的当前工作目录，标准输入关闭，适合非交互命令。命令在 bot 所在主机运行，以 bot 的身份执行。超时会终止整个命令进程组，包括管道和后台子进程。</p><p>新配置默认包含上述 Shell；已有配置的 <code>remote.shells</code> 白名单不会被自动扩大。升级后请通过锅巴配置或 <code>config/global.yaml</code> 把需要的 <code>bash</code>、<code>sh</code>、<code>zsh</code> 加入白名单，并开启 <code>remote.enable</code>。</p><p>管理员入口要求 <code>remote.allow_admin: true</code>。Windows 要求 bot 已以管理员权限运行；Linux 要求 bot 已以 root 身份运行。插件不会自动调用 sudo 或绕过 UAC。</p>`,15)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
